import React, { useContext } from 'react';
import axios from 'axios';

const Eliminar = ({ usuario }) => {

    const handleDelete = async () => {
        if (window.confirm(`¿Estás seguro de que deseas eliminar al usuario "${usuario}"?`)) {
            try {
                // Enviar el nombre del usuario al backend para eliminarlo
                const response = await axios.delete('http://localhost/SERVIDOR/practica/delete_user.php', {
                    data: { usuario }  // Enviamos el nombre de usuario en el cuerpo de la solicitud
                });

                if (response.data.success) {
                    alert('Usuario eliminado con éxito');
                    // Si estás manejando una lista de usuarios, puedes actualizarla aquí
                } else {
                    alert('Error: ' + response.data.message);
                }
            } catch (error) {
                console.error('Error al eliminar el usuario:', error);
                alert('Hubo un error al eliminar el usuario.');
            }
        }
    };

    return (
        <button onClick={handleDelete} style={{ color: 'red' }}>
            Eliminar
        </button>
    );
};

export default Eliminar;
